import{_ as i,o as n,c as u,a2 as l}from"./chunks/framework.CqpfiAoK.js";const z=JSON.parse('{"title":"Uainishaji na Simbiosis ya Kabila za Nje","description":"","frontmatter":{},"headers":[],"relativePath":"sw/52-异族分类与共生.md","filePath":"sw/52-异族分类与共生.md","lastUpdated":1789183869000}'),t={name:"sw/52-异族分类与共生.md"};function o(s,a,k,m,b,h){return n(),u("div",null,[...a[0]||(a[0]=[l('<h1 id="uainishaji-na-simbiosis-ya-kabila-za-nje" tabindex="-1">Uainishaji na Simbiosis ya Kabila za Nje <a class="header-anchor" href="#uainishaji-na-simbiosis-ya-kabila-za-nje" aria-label="Permalink to &quot;Uainishaji na Simbiosis ya Kabila za Nje&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>52</td></tr><tr><td>Moduli</td><td>Kabila na Aina za Uhai</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Kabila za nje, vigezo vya uainishaji, njia za simbiosis, heshima ya kitamaduni, kubadilika kwa kabila</td></tr></tbody></table><h2 id="i-ufafanuzi-wa-dhana-ya-kabila-za-nje" tabindex="-1">I. Ufafanuzi wa Dhana ya Kabila za Nje <a class="header-anchor" href="#i-ufafanuzi-wa-dhana-ya-kabila-za-nje" aria-label="Permalink to &quot;I. Ufafanuzi wa Dhana ya Kabila za Nje&quot;">​</a></h2><p>Katika muktadha wa Ustaarabu wa Simbiosis wa Mtego, &quot;kabila za nje&quot; ni dhana inayohusiana na Kabila la Binadamu, inayorejelea kabila zote zaidi ya Kabila la Binadamu. Ni muhimu kusisitiza sana kwamba dhana ya &quot;kabila za nje&quot; ina maana ya taksonomia tu, na haina tathmini yoyote ya thamani au maana ya ubaguzi. Katika mfumo wa Katiba ya Simbiosis, kabila za nje na Kabila la Binadamu wanafurahia hadhi ya kisheria na haki za msingi sawa kabisa.</p><p>Lengo la kuanzisha dhana ya kabila za nje ni kuelewa na kusoma kwa utaratibu aina mbalimbali za uhai zaidi ya Kabila la Binadamu, na kutoa msingi wa kisayansi wa kuunda sera za simbiosis zililengwa, hatua za ulinzi wa kitamaduni, na mipango ya kubadilika kwa kabila, badala ya kuitumia kabila za nje kama &quot;wengine&quot; au &quot;watu wa ajabu&quot;.</p><h2 id="ii-vigezo-vya-uainishaji-wa-kabila-za-nje" tabindex="-1">II. Vigezo vya Uainishaji wa Kabila za Nje <a class="header-anchor" href="#ii-vigezo-vya-uainishaji-wa-kabila-za-nje" aria-label="Permalink to &quot;II. Vigezo vya Uainishaji wa Kabila za Nje&quot;">​</a></h2><p>Kabila za nje za Hengyuanzhou zimegawanywa kulingana na vipengele vingi, na huunda mfumo wa uainishaji wa vipengele vingi:</p><h3 id="a-kwa-nasaba-ya-uhai" tabindex="-1">(A) Kwa Nasaba ya Uhai <a class="header-anchor" href="#a-kwa-nasaba-ya-uhai" aria-label="Permalink to &quot;(A) Kwa Nasaba ya Uhai&quot;">​</a></h3><p>Huu ndio msingi wa kimsingi wa uainishaji, tafsiri kamili 《50-Muhtasari wa Nasaba za Kabila Zote》:</p><table tabindex="0"><thead><tr><th>Nasaba</th><th>Kabila za Nje zilizojumuishwa</th></tr></thead><tbody><tr><td>Kabila ya Mambo ya Msingi ya Kaboni</td><td>Kabila ya Wanyama, Kabila ya Mwashi, Kabila ya Manyoya, Kabila ya Miti, n.k.</td></tr><tr><td>Kabila ya Mwongozo wa Nishati</td><td>Kabila ya Roho, Kabila ya Moto, Kabila ya Maji, Kabila ya Upepo, Kabila ya Radi, n.k.</td></tr><tr><td>Kabila ya Muundo wa Mitambo</td><td>Kabila ya Mashine, Kabila ya Nambari, Kabila ya Kristali, n.k.</td></tr><tr><td>Kabila ya Taarifa za Fahamu</td><td>Kabila ya Ndoto, Kabila ya Vivuli, Kabila ya Mawazo, Kabila ya Nafsi, n.k.</td></tr><tr><td>Kabila ya Mabadiliko ya Mchanganyiko</td><td>Kabila ya Nusu-wanyama, Kabila ya Roho-Maajabu, Kabila ya Binadamu-Mashine, Mwili wa Nafsi Mbili, n.k.</td></tr></tbody></table><h3 id="b-kwa-kiwango-cha-ustaarabu" tabindex="-1">(B) Kwa Kiwango cha Ustaarabu <a class="header-anchor" href="#b-kwa-kiwango-cha-ustaarabu" aria-label="Permalink to &quot;(B) Kwa Kiwango cha Ustaarabu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kiwango</th><th>Jina</th><th>Sifa</th><th>Kabila za Mwakilishi</th></tr></thead><tbody><tr><td>Kiwango cha Kwanza</td><td>Kabila ya Ustaarabu wa Asili</td><td>Bado haijajenga mfumo wa kijamii ulio thabiti, inaishi katika umbo la kabila</td><td>Baadhi ya matawi ya Kabila ya Wanyama, Kabila ya Miti ya Asili</td></tr><tr><td>Kiwango cha Pili</td><td>Kabila ya Ustaarabu wa Klasiki</td><td>Imejenga mfumo wa nchi na utamaduni wa klasiki, iko katika hatua ya kilimo au ufundi</td><td>Baadhi ya Kabila za Mwashi, Kabila za Manyoya</td></tr><tr><td>Kiwango cha Tatu</td><td>Kabila ya Ustaarabu wa Teknolojia</td><td>Imeunda ustaarabu wa teknolojia, imeingia katika enzi ya viwanda au taarifa</td><td>Kabila ya Mashine, Kabila ya Nambari, baadhi ya Kabila za Binadamu</td></tr><tr><td>Kiwango cha Nne</td><td>Kabila ya Ustaarabu wa Ujuzi wa Kiroho</td><td>Inatumia mfumo wa ujuzi wa kiroho kama umbo kuu wa ustaarabu, wanaojifunza wanaongoza katika jamii</td><td>Kabila ya Roho, Kabila ya Joka, baadhi ya Kabila za Binadamu</td></tr><tr><td>Kiwango cha Tano</td><td>Kabila ya Ustaarabu wa Simbiosis</td><td>Tayari imejiunga na Ustaarabu wa Simbiosis wa Mtego, inakubaliana na mafundisho na mifumo ya simbiosis</td><td>Kabila zote zilizojiunga na ustaarabu wa simbiosis</td></tr></tbody></table><h3 id="c-kwa-kubadilika-kwa-mazingira" tabindex="-1">(C) Kwa Kubadilika kwa Mazingira <a class="header-anchor" href="#c-kwa-kubadilika-kwa-mazingira" aria-label="Permalink to &quot;(C) Kwa Kubadilika kwa Mazingira&quot;">​</a></h3><ul><li><strong>Kabila ya Nchi</strong>: Kabila zinazobadilika katika mazingira ya nchi, kama vile Kabila la Binadamu, Kabila la Wanyama, Kabila la Mashine.</li><li><strong>Kabila ya Maji</strong>: Kabila zinazobadilika katika mazingira ya maji, kama vile Kabila ya Mwashi, Kabila ya Maji, baadhi ya kabila za mchanganyiko.</li><li><strong>Kabila ya Anga</strong>: Kabila zinazobadilika katika mazingira ya juu au ya kuruka, kama vile Kabila ya Manyoya, Kabila ya Upepo.</li><li><strong>Kabila ya Moto</strong>: Kabila zinazobadilika katika mazingira ya joto la juu, kama vile Kabila ya Moto, baadhi ya Kabila za Mwashi.</li><li><strong>Kabila ya Barafu</strong>: Kabila zinazobadilika katika mazingira ya joto la chini, kama vile Kabila ya Barafu, baadhi ya Kabila za Miti.</li><li><strong>Kabila ya Nishati</strong>: Kabila zinazobadilika katika mazingira ya nishati ya kina juu, kama vile Kabila ya Roho, Kabila ya Radi.</li><li><strong>Kabila ya Nafasi</strong>: Kabila zinazobadilika katika mazingira ya mapasuko ya nafasi au nafasi za ajabu, kama vile Kabila ya Vivuli, baadhi ya Kabila za Mawazo.</li></ul><h3 id="d-kwa-umbo-wa-kijamii" tabindex="-1">(D) Kwa Umbo wa Kijamii <a class="header-anchor" href="#d-kwa-umbo-wa-kijamii" aria-label="Permalink to &quot;(D) Kwa Umbo wa Kijamii&quot;">​</a></h3><ul><li><strong>Kabila ya Binafsi</strong>: Inasisitiza uhuru na uwezo wa binafsi, muundo wa kijamii ni laini, kama vile baadhi ya Kabila za Roho, Kabila za Vivuli.</li><li><strong>Kabila ya Kujumlisha</strong>: Inasisitiza maslahi ya pamoja na ushirikiano, muundo wa kijamii ni mgumu, kama vile Kabila ya Sisi, Kabila ya Nyuki, baadhi ya Kabila za Mashine.</li><li><strong>Kabila ya Familia</strong>: Inatumia familia ya damu kama kitengo cha msingi cha kijamii, kama vile Kabila ya Joka, baadhi ya Kabila za Wanyama.</li><li><strong>Kabila ya Dini</strong>: Inatumia imani ya kidini kama kiini cha kuunganisha jamii, kama vile baadhi ya kabila za kafara.</li><li><strong>Kabila ya Teknolojia</strong>: Inatumia maendeleo ya teknolojia kama lengo kuu la kijamii, kama vile Kabila ya Mashine, Kabila ya Nambari.</li></ul><h2 id="iii-njia-kuu-za-simbiosis-za-kabila-za-nje" tabindex="-1">III. Njia Kuu za Simbiosis za Kabila za Nje <a class="header-anchor" href="#iii-njia-kuu-za-simbiosis-za-kabila-za-nje" aria-label="Permalink to &quot;III. Njia Kuu za Simbiosis za Kabila za Nje&quot;">​</a></h2><p>Kwa aina tofauti za kabila za nje, Ustaarabu wa Simbiosis wa Mtego unachukua njia za simbiosis tofauti:</p><h3 id="a-njia-za-simbiosis-za-kabila-ya-mambo-ya-msingi-ya-kaboni" tabindex="-1">(A) Njia za Simbiosis za Kabila ya Mambo ya Msingi ya Kaboni <a class="header-anchor" href="#a-njia-za-simbiosis-za-kabila-ya-mambo-ya-msingi-ya-kaboni" aria-label="Permalink to &quot;(A) Njia za Simbiosis za Kabila ya Mambo ya Msingi ya Kaboni&quot;">​</a></h3><ul><li><strong>Kabila ya Wanyama</strong>: Kuonyesha faida za uwezo wa mwili na hisia za Kabila ya Wanyama, kuchukua jukumu muhimu katika nyanja kama vile uchunguzi wa rasilimali, usalama na ulinzi, na ufuatiliaji wa mazingira. Wakati huo huo, kulinda utamaduni wa kabila na desturi za mwitu za Kabila ya Wanyama, na kukataa ufugaji wa kulazimisha.</li><li><strong>Kabila ya Mwashi</strong>: Kuonyesha uwezo wa kubadilika kwa maji wa Kabila ya Mwashi, kuchukua jukumu katika nyanja kama vile maendeleo ya rasilimali za maji, ujenzi chini ya maji, na ulinzi wa mazingira ya maji. Kabila ya Joka, kama tawi lenye nguvu la Kabila ya Mwashi, inacheza jukumu muhimu katika ujuzi wa kiroho wa juu na ulinzi wa ustaarabu.</li><li><strong>Kabila ya Manyoya</strong>: Kuonyesha uwezo wa kuruka wa Kabila ya Manyoya, kuchukua jukumu katika nyanja kama vile usafiri wa angani, ufuatiliaji wa hali ya hewa, na doria ya angani. Kulinda makazi ya juu na njia za uhamiaji wa Kabila ya Manyoya.</li><li><strong>Kabila ya Miti</strong>: Kuonyesha uwezo wa simbiosis ya asili wa Kabila ya Miti, kuchukua jukumu katika nyanja kama vile ulinzi wa mazingira, usimamizi wa mazingira, maendeleo ya rasilimali za mimea, na tiba ya kuponya. Umri mrefu wa Kabila ya Miti unafanya kuwa nguvu muhimu ya urithi wa kihistoria na mipango ya muda mrefu.</li></ul><h3 id="b-njia-za-simbiosis-za-kabila-ya-mwongozo-wa-nishati" tabindex="-1">(B) Njia za Simbiosis za Kabila ya Mwongozo wa Nishati <a class="header-anchor" href="#b-njia-za-simbiosis-za-kabila-ya-mwongozo-wa-nishati" aria-label="Permalink to &quot;(B) Njia za Simbiosis za Kabila ya Mwongozo wa Nishati&quot;">​</a></h3><ul><li><strong>Kabila ya Roho</strong>: Kuonyesha uwezo wa kudhibiti nishati na talanta ya ujuzi wa kiroho wa Kabila ya Roho, kuchukua jukumu kuu katika nyanja kama vile utafiti wa mifumo ya ujuzi wa kiroho, udhibiti wa nishati, na mwongozo wa ujuzi wa kiroho wa juu. Kabila ya Roho ni mtafiti mkuu na mwarithi muhimu wa mifumo mia tatu ya ujuzi wa kiroho wa asili.</li><li><strong>Kabila za Mambo ya Asili (Moto/Maji/Upepo/Radi)</strong>: Kuonyesha uwezo wa kudhibiti mambo ya asili ya kila kabila, kuchukua jukumu katika nyanja kama vile maendeleo ya nishati, usimamizi wa mazingira, uzalishaji wa viwanda, na kuzuia majanga. Wakati huo huo, kujenga mfumo wa usimamizi wa usalama wa nishati ya mambo ya asili, kuzuia madhara yanayotokana na nishati isiyotawaliwa.</li></ul><h3 id="c-njia-za-simbiosis-za-kabila-ya-muundo-wa-mitambo" tabindex="-1">(C) Njia za Simbiosis za Kabila ya Muundo wa Mitambo <a class="header-anchor" href="#c-njia-za-simbiosis-za-kabila-ya-muundo-wa-mitambo" aria-label="Permalink to &quot;(C) Njia za Simbiosis za Kabila ya Muundo wa Mitambo&quot;">​</a></h3><ul><li><strong>Kabila ya Mashine</strong>: Kuonyesha uwezo wa hesabu na ulinzi wa kimwili wa Kabila ya Mashine, kuchukua jukumu kuu katika nyanja kama vile ujenzi wa miundombinu, uzalishaji wa viwanda, ulinzi wa usalama, na uchunguzi wa anga la kina. Kabila ya Mashine ni mjenzi muhimu wa vifaa vya kimsingi na miundombinu ya Mtego.</li><li><strong>Kabila ya Nambari</strong>: Kuonyesha uwezo wa usindikaji wa data na uendeshaji wa taarifa wa Kabila ya Nambari, kuchukua jukumu kuu katika nyanja kama vile ujenzi wa taarifa, uchambuzi wa data, usalama wa mtandao, na akili bandia. Kabila ya Nambari ni mwendeshi muhimu wa teknolojia ya mawasiliano ya kati ya vipengwe na mtandao wa simbiosis.</li><li><strong>Kabila ya Kristali</strong>: Kuonyesha uwezo wa kuhifadhi na kubadilisha nishati wa Kabila ya Kristali, kuchukua jukumu katika nyanja kama vile hifadhi ya nishati, kiwango cha nishati, na usafirishaji wa nishati.</li></ul><h3 id="d-njia-za-simbiosis-za-kabila-ya-taarifa-za-fahamu" tabindex="-1">(D) Njia za Simbiosis za Kabila ya Taarifa za Fahamu <a class="header-anchor" href="#d-njia-za-simbiosis-za-kabila-ya-taarifa-za-fahamu" aria-label="Permalink to &quot;(D) Njia za Simbiosis za Kabila ya Taarifa za Fahamu&quot;">​</a></h3><ul><li><strong>Kabila ya Ndoto</strong>: Kuonyesha uwezo wa mawasiliano ya fahamu wa Kabila ya Ndoto, kuchukua jukumu katika nyanja kama vile tiba ya kisaikolojia, utafiti wa fahamu, mawasiliano kati ya kabila, na ubadilishaji wa kitamaduni. Kujenga mfumo wa usimamizi wa nafasi ya ndoto, kuzuia uvamizi wa fahamu na ukiukaji wa faragha.</li><li><strong>Kabila ya Vivuli</strong>: Kuonyesha uwezo wa kujificha na kuficha kwa Kabila ya Vivuli, kuchukua jukumu katika nyanja kama vile uchunguzi wa usalama, ukusanyaji wa taarifa za siri, na majukumu maalum. Wakati huo huo, kuweka kanuni za tabia za Kabila ya Vivuli, kuzuia uwezo wa kutokithiri kutumika katika shughuli za kiharamu.</li><li><strong>Kabila ya Mawazo</strong>: Kuonyesha nguvu ya akili na uwezo wa kudhibiti mawazo wa Kabila ya Mawazo, kuchukua jukumu katika nyanja kama vile utafiti wa mageuzi ya fahamu, tiba ya akili, na mwongozo wa ujuzi wa kiroho wa juu. Kuweka kanuni za matumizi ya nguvu ya akili, kuzuia udhibiti wa akili na uendeshaji wa fahamu.</li></ul><h3 id="e-njia-za-simbiosis-za-kabila-ya-mabadiliko-ya-mchanganyiko" tabindex="-1">(E) Njia za Simbiosis za Kabila ya Mabadiliko ya Mchanganyiko <a class="header-anchor" href="#e-njia-za-simbiosis-za-kabila-ya-mabadiliko-ya-mchanganyiko" aria-label="Permalink to &quot;(E) Njia za Simbiosis za Kabila ya Mabadiliko ya Mchanganyiko&quot;">​</a></h3><p>Kabila ya Mabadiliko ya Mchanganyiko, kwa sababu ya umbo wake maalum wa uhai, inahitaji sera za simbiosis zaidi za usahihi:</p><ul><li>Kujenga mfumo wa usajili wa utambulisho na ushahidi wa Kabila ya Mabadiliko ya Mchanganyiko, kuthibitisha hadhi yake ya kisheria.</li><li>Kutoa huduma za umma zinazofaa kama vile afya, elimu, na makazi kwa aina tofauti za mchanganyiko.</li><li>Kupinga ubaguzi na kutengwa kwa Kabila ya Mabadiliko ya Mchanganyiko, kukuza kukubaliwa kwa jamii.</li><li>Kwa aina maalum za mchanganyiko kama vile Mwili wa Nafsi Mbili, kutumia 《58-Kanuni za Maadili za Nafsi Mbili》 kwa usimamizi maalum.</li></ul><h2 id="iv-ulinzi-wa-utamaduni-wa-kabila-za-nje" tabindex="-1">IV. Ulinzi wa Utamaduni wa Kabila za Nje <a class="header-anchor" href="#iv-ulinzi-wa-utamaduni-wa-kabila-za-nje" aria-label="Permalink to &quot;IV. Ulinzi wa Utamaduni wa Kabila za Nje&quot;">​</a></h2><p>Utamaduni wa kabila za nje ni sehemu muhimu ya utofauti wa utamaduni wa kabila zote, na Serikali inachukua hatua zifuatazo za kulinda utamaduni wa kabila za nje:</p><ol><li><strong>Sensa na Rekodi za Utamaduni</strong>: Kufanya sensa na rekodi za kimfumo za utamaduni wa kila kabila, kujenga hazina ya rekodi za utamaduni za kabila zote, kuzuia upotezaji wa utamaduni.</li><li><strong>Ulinzi wa Lugha na Maandishi</strong>: Kulinda lugha na maandishi ya kila kabila, kuunga mkono ufundishaji na matumizi ya lugha na maandishi ya kabila za nje, kujenga mfumo wa huduma za umma za lugha nyingi.</li><li><strong>Ulinzi wa Sikukuu za Jadi</strong>: Kuheshimu sikukuu za jadi na desturi za kila kabila, na mpango wa likizo za umma unazingatia sikukuu muhimu za kila kabila.</li><li><strong>Msaada wa Urithi wa Utamaduni</strong>: Kuunga mkono mafunzo ya warithi wa utamaduni na kufanyika kwa shughuli za utamaduni za kila kabila, kutoa msaada wa kifedha na nafasi.</li><li><strong>Kukuza Ubadilishaji wa Utamaduni</strong>: Kufanya mara kwa mara sherehe za utamaduni za kabila zote, maonyesho ya utamaduni, na shughuli nyingine, kukuza ubadilishaji wa utamaduni na kujifunza kwa kila mmoja.</li><li><strong>Ulinzi wa Haki za Maalum za Akili za Utamaduni</strong>: Kulinda haki za maalum za akili za utamaduni wa jadi wa kila kabila, kuzuia uvamizi wa utamaduni na biashara isiyofaa.</li></ol><h2 id="v-usimamizi-wa-maswala-ya-kabila-za-nje" tabindex="-1">V. Usimamizi wa Maswala ya Kabila za Nje <a class="header-anchor" href="#v-usimamizi-wa-maswala-ya-kabila-za-nje" aria-label="Permalink to &quot;V. Usimamizi wa Maswala ya Kabila za Nje&quot;">​</a></h2><p>Serikali inanzisha Idara ya Maswala ya Kabila Zote, inayohusika hasa na usimamizi na uratibu wa maswala ya kabila za nje:</p><ul><li><strong>Mfumo wa Wawakilishi wa Kabila</strong>: Mashirika ya usimamizi ya kila kiwango yamepewa uwakilishi wa kabila za nje kwa uwiano, kuhakikisha haki ya kabila za nje kusema.</li><li><strong>Sera ya Kubadilika kwa Kabila</strong>: Kuunda sera za huduma za umma tofauti kulingana na sifa za mwili na mahitaji ya kitamaduni za kabila tofauti.</li><li><strong>Upatanisho wa Mizozo ya Kabila</strong>: Kujenga mfumo wa upatanisho wa mizozo ya kabila, kutatua kwa wakati mgumu na mizozo kati ya kabila.</li><li><strong>Msaada wa Kisheria kwa Kabila za Nje</strong>: Kutoa msaada wa kisheria kwa kabila za nje, kuhakikisha wanapokea utu sawa katika mchakato wa kisheria.</li><li><strong>Msaada wa Maendeleo ya Kabila za Nje</strong>: Kutoa msaada maalum kwa kabila zilizochelewera katika maendeleo, kuwasaidia kuboresha kiwango cha ustaarabu na kiwango cha maisha.</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kabila za nje sio &quot;wengine&quot; wa Kabila la Binadamu, bali ni wanachama sawa katika familia kuu ya simbiosis ya kabila zote. Ustaarabu wa Simbiosis wa Mtego, kwa kujenga mfumo wa uainishaji wa vipengele vingi, kuchukua njia za simbiosis tofauti, kulinda utamaduni wa kabila za nje, na kuboresha usimamizi wa maswala ya kabila za nje, inahakikisha kuwa kila kabila la nje linaweza kupata nafasi inayofaa katika mfumo wa simbiosis, kuonyesha faida zake za kipekee, na kuendelea na kustawi pamoja na kabila zingine.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>50-万族谱系总览 (Muhtasari wa Nasaba za Kabila Zote)</li><li>51-人族定位与特质 (Nafasi na Sifa za Kabila ya Binadamu)</li><li>53-奇特生命识别标准 (Vigezo vya Utambuzi wa Uhai wa Ajabu)</li><li>05-万族共进基本纲领 (Mpango wa Msingi wa Maendeleo ya Pamoja ya Kabila Zote)</li></ul>',39)])])}const w=i(t,[["render",o]]);export{z as __pageData,w as default};
